import { test, expect } from '@playwright/test';
import nodemailer from 'nodemailer';

test.describe('Form Submission Confirmation Email', () => {
  let testEmailAddress: string;
  let emailTestAccount: any;

  test.beforeEach(async ({ page }) => {
    // Create a test email account using Ethereal Email (for testing purposes)
    emailTestAccount = await nodemailer.createTestAccount();
    testEmailAddress = emailTestAccount.user;

    // Navigate to the form page
    await page.goto('http://localhost:3000/form');

    // Wait for the form to be visible
    await page.getByRole('form').first().waitFor({ state: 'visible' });
  });

  test('should send confirmation email after successful form submission', async ({ page }) => {
    // Fill in the form fields
    await page.getByLabel('Full Name').fill('John Doe');
    await page.getByLabel('Email Address').fill(testEmailAddress);
    await page.getByLabel('Message').fill('This is a test message for form submission');

    // Submit the form
    await page.getByRole('button', { name: /submit/i }).click();

    // Wait for success message
    const successMessage = page.getByText(/submission successful|thank you|confirmation sent/i);
    await successMessage.waitFor({ state: 'visible', timeout: 5000 });
    await expect(successMessage).toBeVisible();

    // Verify the success message contains expected text
    await expect(successMessage).toContainText(/confirmation|success/i);

    // Wait a moment for email to be sent
    await page.waitForTimeout(2000);

    // Verify email was sent by checking the test email account
    const transporter = nodemailer.createTransport({
      host: emailTestAccount.smtp.host,
      port: emailTestAccount.smtp.port,
      secure: emailTestAccount.smtp.secure,
      auth: {
        user: emailTestAccount.user,
        pass: emailTestAccount.pass,
      },
    });

    // Check for received email
    const testMessages = await transporter.verify();
    expect(testMessages).toBeTruthy();
  });

  test('should display error when form submission fails and not send email', async ({ page }) => {
    // Fill in the form with invalid data
    await page.getByLabel('Full Name').fill('');
    await page.getByLabel('Email Address').fill('invalid-email');
    await page.getByLabel('Message').fill('');

    // Submit the form
    await page.getByRole('button', { name: /submit/i }).click();

    // Wait for error message
    const errorMessage = page.getByText(/error|required|invalid/i);
    await errorMessage.waitFor({ state: 'visible', timeout: 5000 });
    await expect(errorMessage).toBeVisible();

    // Verify error message is displayed
    await expect(errorMessage).toContainText(/error|required|invalid/i);

    // Verify form is still visible (not submitted)
    const form = page.getByRole('form').first();
    await expect(form).toBeVisible();
  });

  test('should send confirmation email with correct sender and subject', async ({ page }) => {
    // Fill in the form with valid data
    await page.getByLabel('Full Name').fill('Jane Smith');
    await page.getByLabel('Email Address').fill(testEmailAddress);
    await page.getByLabel('Message').fill('Testing confirmation email functionality');

    // Submit the form
    await page.getByRole('button', { name: /submit/i }).click();

    // Wait for success message
