    await successMessage.waitFor({ state: 'visible', timeout: 5000 });
    await expect(successMessage).toBeVisible();

    // Verify the page shows confirmation details
    const confirmationDetails = page.getByText(new RegExp(testEmailAddress, 'i'));
    await expect(confirmationDetails).toBeVisible();

    // Wait for email processing
    await page.waitForTimeout(2000);

    // Verify email was sent with correct details
    const transporter = nodemailer.createTransport({
      host: emailTestAccount.smtp.host,
      port: emailTestAccount.smtp.port,
      secure: emailTestAccount.smtp.secure,
      auth: {
        user: emailTestAccount.user,
        pass: emailTestAccount.pass,
      },
    });

    const testMessages = await transporter.verify();
    expect(testMessages).toBeTruthy();
  });

  test('should handle form submission with special characters in message', async ({ page }) => {
    // Fill in the form with special characters
