      secure: emailTestAccount.smtp.secure,
      auth: {
        user: emailTestAccount.user,
        pass: emailTestAccount.pass,
      },
    });

    const testMessages = await transporter.verify();
    expect(testMessages).toBeTruthy();
  });

  test('should not send duplicate confirmation emails on multiple rapid submissions', async ({ page }) => {
